-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM session_records WHERE session_id = 'session-remediate-open-issues-1026'; UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261026_remediate_orch b WHERE b.id = agent_issues.id) WHERE id IN (1000341, 1000344, 1000347, 1000340, 1000350, 1000351) AND EXISTS (SELECT 1 FROM bak_20261026_remediate_orch b WHERE b.id = agent_issues.id); UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261026_remediate_orch b WHERE b.id = 1000470) WHERE class = 'issue-1000470' AND EXISTS (SELECT 1 FROM bak_20261026_remediate_orch b WHERE b.id = 1000470 AND b.verify_probe IS NOT NULL)
-- BACKUP: bak_20261026_remediate_orch
-- SESSION-CLOSEOUT-20261026-REMEDIATE-OPEN-ISSUES (pillar autonomy; SESSION-RECORD-1, OWNER-NO-LOOSE-ENDS-1): the orchestrator row of the session that was asked
-- "REMEDIATE ALL CLOUDFLARE QUNIVERSE OPEN ISSUES IN ORDER OF PRIORITY, IMPACT, SEVERITY, AND EFFORT. RESOLVE, DEPLOY, AND CLOSE ALL OPEN ISSUES" and then (19:57Z, 20:16Z)
-- "APPROVE ALL, RESOLVE ALL, IMPLEMENT ALL, DEPLOY ALL, THEN CLOSEOUT THIS THREAD IMMEDIATELY". It also does the two small things the sub-agents left without a doer:
--   1. issue 1000470 (RESEARCH-WATCHDOG-PROOF-HELD-1): the fix merged in PR 4845 (qnfo-cloud-ops 1.40.1) under another marker than the probe guessed, so the code-read probe
--      looked for the word proof-held, which the source never carries, and could not pass; it now reads the condition the fix added.
--   2. six BP26 issues get the code-task and code-anchor lines the BP26 sub-agent prepared (anchors verified to occur exactly once on main at 20:45Z), so the code loop opens
--      the pull requests (ACT-BRIDGE-1). Nothing else changes: no worker, trigger, cap, guard or probe of another issue.

CREATE TABLE IF NOT EXISTS bak_20261026_remediate_orch AS
SELECT a.id AS id, a.description AS description, (SELECT c.verify_probe FROM remediation_contracts c WHERE c.class = 'issue-' || a.id) AS verify_probe
FROM agent_issues a WHERE a.id IN (1000341, 1000344, 1000347, 1000340, 1000350, 1000351, 1000470);

-- 1. the probe of 1000470 reads the condition the merged fix added
UPDATE remediation_contracts
SET verify_probe = '{"paths": ["qnfo-cloud-ops/worker.js"], "contains": "sinceHeld <= RESEARCH_WATCHDOG_HELD_FRESH_MIN && sinceOk <= RESEARCH_WATCHDOG_PROOF_MIN"}',
    status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), module = 'session-remediate-open-issues-1026',
    action = 'MEASURES the fix: the watchdog returns budget-held only while the proof kick is not yet due (the condition added by PR 4845, qnfo-cloud-ops 1.40.1). The earlier probe looked for the word proof-held, which the merged fix never carries.'
WHERE class = 'issue-1000470' AND instr(verify_probe, 'proof-held') > 0;

-- 2. code-task lines for six BP26 issues (ACT-BRIDGE-1)
UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): AI-interaction disclosure for the personal companion. The sign-in page of personal-api shows a code field and no sentence that the visitor is talking to an AI system (EU AI Act Article 50, metric ai_interaction_disclosure 0.33). Add one visible sentence, This companion is an AI system, next to the 6-digit code field and keep the page markup otherwise unchanged.' || char(10) ||
 'code-task: repo=qnfo-workers path=personal-api/worker.js' || char(10) ||
 'code-anchor: placeholder="6-digit code"'
WHERE id = 1000341 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): the personal companion sends prompts and answers through the AI Gateway with request logging on, so personal text is kept in gateway logs (metric pii_in_logs, records_past_retention). At each of the five runOpts sites add collectLog: false and skipCache: true to the gateway options. The qnfo-ipatent submissions insert (ip_address, user_agent) is the second half and is a separate change.' || char(10) ||
 'code-task: repo=qnfo-workers path=personal-api/worker.js' || char(10) ||
 'code-anchor: const runOpts = { gateway: { id: "default" } };'
WHERE id = 1000344 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): the personal-companion digest is list mail and carries neither List-Unsubscribe nor List-Unsubscribe-Post (metric rfc8058_headers_present 0.6667, RFC 8058). Add both headers to the digest send (List-Unsubscribe-Post: List-Unsubscribe=One-Click) with the existing opt-out address or link, and keep the body unchanged.' || char(10) ||
 'code-task: repo=qnfo-workers path=personal-companion/worker.js' || char(10) ||
 'code-anchor: await env.SEND_EMAIL.send({ to, from: "rowan.quni@qnfo.org", subject, text: body });'
WHERE id = 1000347 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): qnfo-social 0.20.0 ends automated posts with the marker [automated]; the per-channel length table does not reserve its length, so an X or Mastodon post at the limit loses the marker or is cut. Reserve the marker length in CHANNEL_MAX_CHARS handling so every post fits with the marker.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-social/worker.js' || char(10) ||
 'code-anchor: var CHANNEL_MAX_CHARS = { linkedin: 1300, mastodon: 280, twitter: 280, substack: 1300 };'
WHERE id = 1000340 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): metric kv_used_for_locking reads 1: the public gate of qnfo-ops counts requests in a KV key (read, add one, write), which loses updates under concurrency and is a lock by another name. Replace the KV counter with an atomic D1 upsert or a Durable Object counter, keep the limit and the response unchanged.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-ops/worker.js' || char(10) ||
 'code-anchor: const n = Number(await env.OPS_CACHE_KV.get(vk)) || 0;'
WHERE id = 1000350 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

UPDATE agent_issues SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000, description = description || char(10) || char(10) ||
 'REM-ORCH 2026-10-26 (handoff to the code loop, from the BP26 sub-agent): metric gateway_coverage reads 0.416 and ai_cache_hit_rate 0.0974: model calls of q08-signal-engine go straight to env.AI.run without the gateway option. Route the compose call through the AI Gateway (gateway id default) with skipCache: true, because generation must not be served from the default 30-day cache. The calls in qnfo-code-orchestrator and idea-hub are the next two sites and follow the same pattern.' || char(10) ||
 'code-task: repo=qnfo-workers path=q08-signal-engine/worker.js' || char(10) ||
 'code-anchor: var resp = await env.AI.run(modelId, { messages: [{ role: "user", content: prompt }], max_tokens: 1400, temperature: 0.2 }, { signal: AbortSignal.timeout(60000) });'
WHERE id = 1000351 AND status = 'open' AND instr(description, 'REM-ORCH 2026-10-26 (handoff to the code loop') = 0 AND instr(description, 'code-task:') = 0;

-- 3. the session record (one row, honest counts: asked = issues handed to the eight sub-agents, finished = those closed at 20:49Z)
INSERT INTO session_records (
  session_id, wbs_code, agent_name, summary, decisions_made, files_changed,
  commits, infrastructure_changes, handoff_notes, execution_ratio,
  total_tasks, completed_tasks, started_at, completed_at, created_at
)
SELECT
  'session-remediate-open-issues-1026', 'QNFO.OPS', 'claude-code',
  'Asked: remediate all open Cloudflare Quniverse agent_issues in order of priority, impact, severity and effort, resolve, deploy and close all; then (19:57Z, 20:16Z) approve all, resolve all, implement all, deploy all, wrap up and close out immediately. Start (17:40Z, read from qnfo-audit): 333 open (67 critical, 103 high, 161 medium, 1 low), metrics_in_breach 62, issues_over_24h_no_doer 144, about 134 issues standing on a placeholder closing probe (VACUOUS-PROBE-V3-1) that can never pass. Method: read the queue, the contracts and the planner verdicts; split 322 of the issues into eight clusters (research, papers and errata; tickets the fleet loops file about themselves; metric regressions, loops and journeys; doctrine and closing machinery; METRIC-TRIGGER tickets; infrastructure and ops; owner tasks and reach; the BP26 catalogue); ran eight sub-agents in private worktrees under work claims, each to fix the cause, replace placeholder probes by probes that measure the defect, and ship through CI-applied migrations and canonical-deploy pull requests; reviewed their pull requests, merged the green ones after the owner order, and landed three orphaned patches (EMAIL-TIER2-GATE-1 qnfo-email 2.12.2 as PR 4940, TOMBSTONE-AUDIT-ROW-1 as PR 4936, GATE-GREEN-1 as PR 4964 which turns the red deploy-gate on main green again) plus the CI wiring of the first-pass test (PR 4965). Result read from qnfo-audit at 20:49Z: of the 322 issues handed out, 136 are closed with evidence (25 critical, 45 high) and 186 are open (44 critical, 54 high), each with a doer, a clock or an owner step; all open agent_issues 333 to 257 (critical 67 to 45, high 103 to 77, medium 161 to 114, low 1 to 21 because newly measured BP26 metrics file their own low tickets). About 125 pull requests of the sub-agents were merged with their migrations read as ok in migration_runs or their deploy read live. Guards: issue_wontfix_share_7d stayed 0.0 and remediation_latest_pass_pct_7d rose from 79.5 to 80.3 during the run (rem-a2 read). The headline got worse and the cause is measurement, not decay: metrics_in_breach 62 to 78 because 16 BP26 metrics went from unmeasured to measured and failing (pii_in_logs 83, records_past_retention 886, agent_tool_calls_outside_allowlist 44, dmarc_aligned_pass_rate 0.92, rfc8058_headers_present 0.67, security_headers_pass 0.85, turnstile_on_public_forms 0, third_party_trackers 5, workers_with_source_maps 0, deploys_via_gradual 0, gateway_coverage 0.42, ai_cache_hit_rate 0.10 and others) plus five flapping readings and two new metrics of other sessions; cleared: breach_code_task_pct, fleet_cost_bound_month_usd (329 to 296), orphaned_leases (215 to 0, PR 4729 of another session), worker_count 36 to 35. Counting rule: total_tasks is the number of issues handed to the sub-agents (322; the 12 issues under another live claim at the start were left to their holders: 8 are closed now and 4 are open), completed_tasks the number of those closed at 20:49Z; closed here means closed through a passing measuring probe, a superseding issue id or written close evidence, never wontfix.',
