-- 4. the decision, append-only
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-remediate-open-issues-1026',
  'a closing probe that looks for a guessed word the merged fix never carries cannot pass and keeps a fixed issue open for ever; a follow-up that is only prose is lost, so it becomes a code-task line the code loop executes',
  'REMEDIATE-ORCH-CLOSEOUT-1: issue 1000470 probe re-pointed to the condition PR 4845 added; code-task and code-anchor lines appended to 1000341, 1000344, 1000347, 1000340, 1000350 and 1000351; one session_records row',
  'qnfo-cloud-ops/worker.js on main at 20:45Z carries sinceHeld <= RESEARCH_WATCHDOG_HELD_FRESH_MIN && sinceOk <= RESEARCH_WATCHDOG_PROOF_MIN once and the word proof-held zero times; each of the six anchors occurs exactly once in its file on main (node check at 20:45Z); the remediation contract of 1000470 read fail on the old marker',
  'applied through the canonical path on merge: one contract probe changed, six issue descriptions extended, one session record and this decision row written',
  'one remediation_contracts row, six agent_issues descriptions, two append-only rows; no worker, trigger, cap, guard or probe of another issue changed',
  'the Rollback header restores the six descriptions and the contract probe from bak_20261026_remediate_orch and deletes the session record',
  'a-merged-fix-gets-a-probe-that-can-pass',
  'the contract of 1000470 passes on its next hourly round and closes the issue through the trigger; the six BP26 issues count a doer through their code-task line; falsifier: 1000470 closed by anything other than a passing probe',
  NULL, 'code-read of qnfo-cloud-ops/worker.js, anchor occurrence count in six files'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'REMEDIATE-ORCH-CLOSEOUT-1:%');
